# Lei 9.784/99 — v3. Tupla: (ponto, [átomos], g, padrao, dif, enunciado, comentário, tipo_erro, tag_par, extra)
# tag_par liga itens gêmeos C/E sobre o mesmo ponto. extra: dict opcional (fonte, risco, formato).
Q = [
# P01 — Aplicação e conceitos (art. 1º)
("P01",["1"],"C","conceito_correto",1,"Os preceitos da Lei n.º 9.784/1999 alcançam os órgãos do Legislativo e do Judiciário da União quando estes exercem função administrativa, e não apenas a Administração federal direta e indireta.","Art. 1º, § 1º.","","p01a",{}),
("P01",["1"],"E","restricao_indevida",1,"Por pertencerem a Poderes diversos do Executivo, a Câmara dos Deputados e os tribunais da União ficam fora do campo de incidência da Lei n.º 9.784/1999, mesmo quando decidem questões administrativas.","Art. 1º, § 1º: aplica-se aos órgãos do Legislativo e do Judiciário da União no desempenho de função administrativa.","exclui Poderes Legislativo e Judiciário","p01a",{}),
("P01",["1"],"C","caso_concreto",2,"A decisão da Câmara dos Deputados sobre requerimento de servidor de seu quadro para concessão de vantagem pessoal é função administrativa e, por isso, submete-se à Lei n.º 9.784/1999.","Art. 1º, § 1º: o Legislativo da União fica sujeito à lei ao desempenhar função administrativa; apreciar requerimento de servidor é atividade administrativa, não legislativa.","","p01b",{}),
("P01",["1"],"E","caso_concreto",2,"A votação de proposição legislativa em plenário da Câmara dos Deputados é função típica do Poder Legislativo, mas segue o rito da Lei n.º 9.784/1999, que disciplina processos no âmbito da Administração federal.","A lei só alcança o Legislativo quando este exerce função administrativa (art. 1º, § 1º); o processo legislativo é regido pela CF e pelo Regimento Interno.","aplica a lei à função legislativa","p01b",{}),
("P01",["1"],"E","confusao_instituto",2,"Nos termos da Lei n.º 9.784/1999, órgão é a unidade de atuação dotada de personalidade jurídica, e entidade, a unidade de atuação que integra a estrutura da Administração direta.","Art. 1º, § 2º, I e II: órgão é unidade de atuação integrante da estrutura da Administração direta e indireta; entidade é a unidade dotada de personalidade jurídica. Os conceitos foram trocados.","troca órgão x entidade","p01c",{}),
("P01",["1"],"C","confusao_instituto",2,"Nos termos da Lei n.º 9.784/1999, entidade é a unidade de atuação dotada de personalidade jurídica, e órgão, a unidade de atuação que integra a estrutura da Administração direta ou da indireta.","Art. 1º, § 2º, I e II.","","p01c",{}),
("P01",["1"],"C","conceito_correto",1,"Autoridade, para fins da Lei n.º 9.784/1999, é o servidor ou agente público dotado de poder de decisão, e não qualquer servidor que atue no processo.","Art. 1º, § 2º, III.","","p01d",{}),
("P01",["1"],"E","restricao_indevida",1,"Autoridade, para fins da Lei n.º 9.784/1999, é qualquer servidor ou agente público que atue no processo administrativo, ainda que desprovido de poder de decisão.","Art. 1º, § 2º, III: autoridade é o servidor ou agente público dotado de poder de decisão.","amplia o conceito de autoridade","p01d",{}),
# P02 — Princípios (art. 2º, caput)
("P02",["2"],"C","conceito_correto",1,"Entre os princípios que o art. 2º da Lei n.º 9.784/1999 enumera para a Administração Pública estão a segurança jurídica, o interesse público e a eficiência.","Art. 2º, caput.","","p02a",{}),
("P02",["2"],"E","excecao_omitida",3,"O art. 2º da Lei n.º 9.784/1999 enuncia, de forma expressa, os princípios da legalidade, da impessoalidade, da moralidade, da publicidade e da eficiência, repetindo o rol do art. 37 da Constituição Federal.","Art. 2º, caput: legalidade, finalidade, motivação, razoabilidade, proporcionalidade, moralidade, ampla defesa, contraditório, segurança jurídica, interesse público e eficiência. Impessoalidade e publicidade não constam do caput (o rol não repete o do art. 37 da CF).","rol do art. 37 da CF no lugar do art. 2º","p02a",{}),
("P02",["2"],"E","confusao_instituto",3,"A impessoalidade figura de forma expressa entre os princípios arrolados no caput do art. 2º da Lei n.º 9.784/1999, ao lado da legalidade e da moralidade.","Art. 2º, caput: o rol não menciona a impessoalidade (embora o parágrafo único, III, trate de objetividade e vedação de promoção pessoal).","inclui princípio ausente do rol","p02b",{}),
("P02",["2"],"C","confusao_instituto",3,"Os princípios da razoabilidade, da proporcionalidade e da segurança jurídica constam expressamente do rol do art. 2º da Lei n.º 9.784/1999, ainda que não estejam no caput do art. 37 da Constituição.","Art. 2º, caput; o art. 37 da CF, na redação original, não os enumera.","","p02b",{}),
("P02",["2"],"E","troca_efeito",2,"A ampla defesa e o contraditório, por serem garantias constitucionais do processo judicial, não integram o rol de princípios que a Lei n.º 9.784/1999 impõe à Administração nos processos administrativos.","Art. 2º, caput: ampla defesa e contraditório constam do rol de princípios da Administração; a CF (art. 5º, LV) também os assegura nos processos administrativos.","exclui ampla defesa e contraditório","p02c",{}),
("P02",["2"],"C","conceito_correto",2,"A finalidade e a motivação são princípios da Administração Pública expressamente referidos no art. 2º da Lei n.º 9.784/1999.","Art. 2º, caput.","","p02c",{}),
# P03 — Critérios (art. 2º, p.ú.)
("P03",["2.II"],"C","conceito_correto",2,"É vedada a renúncia, total ou parcial, de poderes ou competências nos processos administrativos, salvo autorização em lei.","Art. 2º, parágrafo único, II.","","p03a",{}),
("P03",["2.II"],"E","excecao_omitida",2,"A Administração pode renunciar parcialmente a poderes ou competências nos processos administrativos, desde que o faça por decisão motivada da autoridade competente.","Art. 2º, parágrafo único, II: a renúncia, total ou parcial, é vedada, salvo autorização em lei; a motivação da autoridade não a legitima.","troca fonte da autorização (lei x decisão motivada)","p03a",{}),
("P03",["2.III"],"C","conceito_correto",1,"Nos processos administrativos, deve-se observar a objetividade no atendimento do interesse público, sendo vedada a promoção pessoal de agentes ou autoridades.","Art. 2º, parágrafo único, III.","","p03b",{}),
("P03",["2.III"],"E","troca_efeito",2,"A vedação de promoção pessoal de agentes ou autoridades nos processos administrativos decorre do critério da divulgação oficial dos atos administrativos, e não do critério da objetividade no atendimento do interesse público.","Art. 2º, parágrafo único, III: a vedação de promoção pessoal está ligada à objetividade no atendimento do interesse público.","liga vedação ao critério errado","p03b",{}),
("P03",["2.V"],"C","excecao_omitida",2,"A divulgação oficial dos atos administrativos é critério a ser observado nos processos, ressalvadas as hipóteses de sigilo previstas na Constituição.","Art. 2º, parágrafo único, V.","","p03c",{}),
("P03",["2.V"],"E","troca_autoridade",3,"A divulgação oficial dos atos administrativos admite ressalva nas hipóteses de sigilo definidas em ato normativo do órgão responsável pelo processo.","Art. 2º, parágrafo único, V: as ressalvas são as hipóteses de sigilo previstas na Constituição, não as criadas por ato do órgão.","troca fonte do sigilo (CF x ato do órgão)","p03c",{}),
("P03",["2.VI"],"C","conceito_correto",2,"Veda-se a imposição de obrigações, restrições e sanções em medida superior à estritamente necessária ao atendimento do interesse público, critério que traduz a adequação entre meios e fins.","Art. 2º, parágrafo único, VI.","","p03d",{}),
("P03",["2.VI"],"E","troca_efeito",3,"A proibição de impor obrigações, restrições e sanções além do estritamente necessário ao interesse público é uma decorrência do critério da impulsão de ofício do processo administrativo.","Art. 2º, parágrafo único, VI (adequação entre meios e fins); impulsão de ofício é o inciso XII.","troca critério (VI x XII)","p03d",{}),
("P03",["2.XI"],"C","excecao_omitida",1,"Nos processos administrativos, é proibida a cobrança de despesas processuais, ressalvadas as previstas em lei.","Art. 2º, parágrafo único, XI.","","p03e",{}),
("P03",["2.XI"],"E","excecao_omitida",1,"Nos processos administrativos, é proibida a cobrança de despesas processuais, ressalvadas as fixadas em regulamento pelo órgão competente.","Art. 2º, parágrafo único, XI: a ressalva é para as despesas previstas em lei.","troca lei por regulamento","p03e",{}),
("P03",["2.XII"],"C","conceito_correto",2,"A Administração deve impulsionar de ofício o processo administrativo, sem prejuízo da atuação dos interessados.","Art. 2º, parágrafo único, XII.","","p03f",{}),
("P03",["2.XII"],"E","restricao_indevida",2,"Cabe aos interessados, e não à Administração, o impulso do processo administrativo, que somente avança quando provocado por quem tem interesse na decisão.","Art. 2º, parágrafo único, XII: o impulso é de ofício, sem prejuízo da atuação dos interessados.","transfere impulso ao interessado","p03f",{}),
("P03",["2.XIII"],"C","conceito_correto",3,"A interpretação da norma administrativa deve garantir o fim público a que ela se dirige, sendo vedada a aplicação retroativa de nova interpretação.","Art. 2º, parágrafo único, XIII.","","p03g",{}),
("P03",["2.XIII"],"E","troca_efeito",3,"Quando a Administração altera a interpretação de uma norma administrativa, a nova interpretação deve alcançar também os atos praticados sob a interpretação anterior, em homenagem ao interesse público.","Art. 2º, parágrafo único, XIII: é vedada a aplicação retroativa de nova interpretação.","admite retroação de nova interpretação","p03g",{}),
("P03",["2.X"],"C","conceito_correto",2,"Nos processos de que possam resultar sanções e nas situações de litígio, garantem-se os direitos à comunicação, às alegações finais, à produção de provas e à interposição de recursos.","Art. 2º, parágrafo único, X.","","p03h",{}),
("P03",["2.X"],"E","restricao_indevida",2,"Os direitos à comunicação, às alegações finais, à produção de provas e à interposição de recursos são assegurados em qualquer processo administrativo, ainda que dele não possam resultar sanções nem haja litígio.","Art. 2º, parágrafo único, X: a garantia é prevista para os processos de que possam resultar sanções e para as situações de litígio.","amplia o alcance da garantia","p03h",{}),
# P04 — Direitos e deveres do administrado
("P04",["3"],"C","conceito_correto",1,"O administrado pode fazer-se assistir por advogado de modo facultativo, salvo quando a lei tornar obrigatória a representação.","Art. 3º, IV.","","p04a",{}),
("P04",["3"],"E","troca_efeito",2,"É obrigatória a assistência por advogado ao administrado em todo processo administrativo, sob pena de nulidade dos atos praticados sem defesa técnica.","Art. 3º, IV: a assistência por advogado é facultativa, salvo quando a lei exigir representação. Ver também a Súmula Vinculante 5 do STF (falta de defesa técnica em PAD não ofende a CF).","torna obrigatória a defesa técnica","p04a",{}),
("P04",["3"],"C","conceito_correto",2,"O direito do administrado a formular alegações e apresentar documentos antes da decisão acarreta, para o órgão competente, o dever de considerá-los.","Art. 3º, III.","","p04b",{}),
("P04",["3"],"E","troca_efeito",2,"Os documentos e alegações apresentados pelo administrado antes da decisão podem ser recebidos pelo órgão competente sem que este tenha o dever de levá-los em consideração no julgamento.","Art. 3º, III: alegações e documentos serão objeto de consideração pelo órgão competente.","retira dever de considerar","p04b",{}),
("P04",["4"],"C","conceito_correto",1,"Constituem deveres do administrado perante a Administração expor os fatos conforme a verdade, agir com lealdade, urbanidade e boa-fé e não proceder de modo temerário.","Art. 4º, I a III.","","p04c",{}),
("P04",["4"],"E","excecao_omitida",2,"O administrado deve colaborar com o esclarecimento dos fatos apenas quando for o autor do pedido, não sendo exigível colaboração de quem figure como interessado sem ter iniciado o processo.","Art. 4º, IV: é dever do administrado prestar as informações solicitadas e colaborar para o esclarecimento dos fatos, sem distinguir entre quem iniciou o processo e demais interessados.","restringe dever a quem iniciou o processo","p04c",{}),
# P05 — Início e requerimento
("P05",["5"],"C","conceito_correto",1,"O processo administrativo pode iniciar-se de ofício ou a pedido de interessado.","Art. 5º.","","p05a",{}),
("P05",["6"],"C","excecao_omitida",2,"O requerimento inicial do interessado deve ser formulado por escrito, salvo nos casos em que a solicitação oral for admitida.","Art. 6º, caput.","","p05b",{}),
("P05",["6"],"E","restricao_indevida",2,"O requerimento inicial do interessado deve ser formulado por escrito em todos os casos, pois a Lei n.º 9.784/1999 não admite solicitação oral.","Art. 6º, caput: a forma escrita é a regra, salvo casos em que se admita solicitação oral.","elimina a exceção da solicitação oral","p05b",{}),
("P05",["6"],"C","caso_concreto",2,"Servidor do protocolo que recusa receber documentos de um requerente por entender que a petição está incompleta desrespeita a lei, pois deveria orientá-lo quanto ao suprimento das falhas.","Art. 6º, parágrafo único: é vedada a recusa imotivada de recebimento de documentos, devendo o servidor orientar o interessado.","","p05c",{}),
("P05",["6"],"E","caso_concreto",2,"Servidor do protocolo pode recusar o recebimento de documentos de requerente quando a petição estiver incompleta, cabendo ao interessado, por conta própria, descobrir e sanar as falhas.","Art. 6º, parágrafo único: a recusa imotivada é vedada e o servidor deve orientar o interessado quanto ao suprimento das falhas.","admite recusa e retira dever de orientar","p05c",{}),
("P05",["8"],"C","conceito_correto",2,"Pedidos de vários interessados com conteúdo e fundamentos idênticos podem ser formulados em um único requerimento, salvo preceito legal em contrário.","Art. 8º.","","p05d",{}),
("P05",["7"],"C","conceito_correto",2,"Órgãos e entidades administrativas devem elaborar modelos ou formulários padronizados para assuntos que importem pretensões equivalentes.","Art. 7º.","","p05e",{}),
# P06 — Interessados e capacidade
("P06",["9"],"C","conceito_correto",2,"Quem não iniciou o processo, mas tem direitos ou interesses que possam ser afetados pela decisão, é legitimado como interessado.","Art. 9º, II.","","p06a",{}),
("P06",["9"],"E","restricao_indevida",2,"Somente quem inicia o processo administrativo, como titular de direito ou interesse individual, é legitimado como interessado.","Art. 9º, I a IV: também são interessados os que, sem terem iniciado o processo, possam ser afetados pela decisão, as organizações e associações representativas (interesses coletivos) e as pessoas ou associações legalmente constituídas (interesses difusos).","restringe a legitimação a quem iniciou","p06a",{}),
("P06",["9"],"E","troca_autoridade",3,"Quanto a direitos ou interesses difusos, são legitimados como interessados no processo administrativo os cidadãos e as associações, nos termos do art. 9º da Lei n.º 9.784/1999.","Art. 9º, IV: pessoas ou associações legalmente constituídas. A expressão \"cidadãos ou associações\" aparece no art. 58, IV (legitimidade recursal).","mistura art. 9º, IV com art. 58, IV","p06b",{}),
("P06",["9"],"C","confusao_instituto",3,"As organizações e associações representativas são legitimadas como interessadas quanto a direitos e interesses coletivos, e as pessoas ou associações legalmente constituídas, quanto a direitos ou interesses difusos.","Art. 9º, III e IV.","","p06b",{}),
("P06",["10"],"C","troca_numero",1,"Para fins de processo administrativo, são capazes os maiores de dezoito anos, ressalvada previsão especial em ato normativo próprio.","Art. 10.","","p06c",{}),
("P06",["10"],"E","troca_numero",1,"Para fins de processo administrativo, são capazes os maiores de dezesseis anos, ressalvada previsão especial em ato normativo próprio.","Art. 10: maiores de dezoito anos.","16 no lugar de 18","p06c",{}),
# P07 — Competência, delegação e avocação
("P07",["11"],"C","conceito_correto",1,"A competência administrativa é irrenunciável e deve ser exercida pelo órgão a que foi atribuída como própria, salvo os casos de delegação e avocação legalmente admitidos.","Art. 11.","","p07a",{}),
("P07",["11"],"E","troca_efeito",1,"A competência administrativa é renunciável pelo titular quando houver conveniência administrativa devidamente motivada, desde que comunicada à autoridade superior.","Art. 11: a competência é irrenunciável; só se admitem delegação e avocação legais.","torna renunciável","p07a",{}),
("P07",["12"],"C","excecao_omitida",3,"A delegação de competência pode ocorrer em favor de órgãos ou titulares que não sejam hierarquicamente subordinados ao delegante, se isso for conveniente por razões de índole técnica, social, econômica, jurídica ou territorial.","Art. 12, caput.","","p07b",{}),
("P07",["12"],"E","restricao_indevida",3,"A delegação de competência só pode ser feita a órgãos ou titulares hierarquicamente subordinados ao delegante, em razão da necessária relação de hierarquia entre delegante e delegado.","Art. 12, caput: a delegação é possível ainda que o delegado não seja hierarquicamente subordinado.","exige subordinação hierárquica","p07b",{}),
("P07",["12"],"C","conceito_correto",2,"A regra da delegação de competência aplica-se também à delegação dos órgãos colegiados aos respectivos presidentes.","Art. 12, parágrafo único.","","p07c",{}),
("P07",["13"],"C","conceito_correto",1,"Não podem ser objeto de delegação a edição de atos de caráter normativo, a decisão de recursos administrativos e as matérias de competência exclusiva do órgão ou autoridade.","Art. 13, I a III.","","p07d",{}),
("P07",["13"],"E","troca_efeito",1,"A edição de atos de caráter normativo e a decisão de recursos administrativos podem ser delegadas, mas não as matérias de competência exclusiva do órgão ou autoridade.","Art. 13, I a III: os três não podem ser delegados.","admite delegar normativo e recurso","p07d",{}),
("P07",["13"],"E","caso_concreto",2,"O Presidente de autarquia federal delegou a um diretor, por portaria publicada, a decisão de recursos administrativos interpostos contra atos do próprio Presidente, o que é válido porque o ato de delegação especificou matéria, limites e duração.","Art. 13, II: a decisão de recursos administrativos não pode ser objeto de delegação, ainda que o ato cumpra os requisitos do art. 14.","delegação vedada pelo art. 13, II","p07e",{}),
("P07",["13"],"C","caso_concreto",2,"É inválida a delegação, por ministro de Estado a um secretário, da competência para editar ato normativo geral sobre matéria de sua pasta, ainda que o ato delegatório tenha sido publicado no meio oficial.","Art. 13, I: a edição de atos de caráter normativo não pode ser delegada; a publicação não supre a vedação.","","p07e",{}),
("P07",["14"],"C","conceito_correto",2,"O ato de delegação e sua revogação devem ser publicados no meio oficial.","Art. 14, caput.","","p07f",{}),
("P07",["14"],"E","troca_autoridade",2,"A publicação no meio oficial é exigida para o ato de delegação, mas não para o ato que a revoga, que produz efeitos com a simples comunicação ao delegado.","Art. 14, caput: o ato de delegação e sua revogação deverão ser publicados no meio oficial.","dispensa publicação da revogação","p07f",{}),
("P07",["14"],"C","conceito_correto",3,"O ato de delegação deve especificar as matérias e poderes transferidos, os limites da atuação do delegado, a duração, os objetivos da delegação e o recurso cabível, podendo conter ressalva de exercício da atribuição delegada.","Art. 14, § 1º.","","p07g",{}),
("P07",["14"],"E","troca_efeito",3,"A delegação de competência é irrevogável antes do término do prazo nela fixado, em respeito à segurança jurídica do delegado.","Art. 14, § 2º: o ato de delegação é revogável a qualquer tempo pela autoridade delegante.","torna a delegação irrevogável","p07g",{}),
("P07",["14"],"C","consequencia",3,"As decisões adotadas por delegação devem mencionar explicitamente essa qualidade e consideram-se editadas pelo delegado.","Art. 14, § 3º.","","p07h",{}),
("P07",["14"],"E","troca_autoridade",3,"As decisões adotadas por delegação consideram-se editadas pela autoridade delegante, que responde por elas perante os administrados.","Art. 14, § 3º: consideram-se editadas pelo delegado.","atribui a decisão ao delegante","p07h",{}),
("P07",["15"],"C","conceito_correto",2,"A avocação temporária de competência atribuída a órgão hierarquicamente inferior é permitida em caráter excepcional e por motivos relevantes devidamente justificados.","Art. 15.","","p07i",{}),
("P07",["15"],"E","troca_efeito",2,"A avocação de competência atribuída a órgão hierarquicamente inferior pode ser feita de modo permanente, desde que haja motivos relevantes devidamente justificados.","Art. 15: a avocação é temporária e excepcional.","torna a avocação permanente","p07i",{}),
("P07",["17"],"C","caso_concreto",2,"Se nenhuma norma indicar a autoridade competente para decidir determinado pedido, o processo deve ser iniciado perante a autoridade de menor grau hierárquico para decidir.","Art. 17.","","p07j",{}),
("P07",["17"],"E","caso_concreto",2,"Se nenhuma norma indicar a autoridade competente para decidir determinado pedido, o processo deve ser iniciado perante a autoridade de maior grau hierárquico do órgão.","Art. 17: autoridade de menor grau hierárquico para decidir.","troca menor por maior grau","p07j",{}),
# P08 — Impedimento e suspeição
("P08",["18"],"C","conceito_correto",2,"É impedido de atuar em processo administrativo o servidor que esteja litigando, judicial ou administrativamente, com o interessado ou com o respectivo cônjuge ou companheiro.","Art. 18, III.","","p08a",{}),
("P08",["18"],"E","confusao_instituto",3,"A amizade íntima ou a inimizade notória do servidor com o interessado configura hipótese de impedimento, que o proíbe de atuar no processo.","Art. 20: amizade íntima e inimizade notória são hipóteses de suspeição, que pode ser arguida; impedimento está no art. 18.","troca suspeição por impedimento","p08a",{}),
("P08",["20"],"C","confusao_instituto",3,"Amizade íntima ou inimizade notória com algum dos interessados, ou com seus cônjuges, companheiros, parentes e afins até o terceiro grau, autoriza a arguição de suspeição da autoridade ou servidor.","Art. 20.","","p08b",{}),
("P08",["18"],"E","troca_numero",2,"É impedido de atuar o servidor que tenha participado como testemunha do processo ou cujo cônjuge, companheiro ou parente e afim até o quinto grau tenha participado como perito ou representante.","Art. 18, II: parentes e afins até o terceiro grau.","quinto grau no lugar de terceiro","p08g",{}),
("P08",["18"],"C","caso_concreto",2,"Servidora que será ouvida como testemunha em processo administrativo está impedida de atuar nele como autoridade instrutora.","Art. 18, II: é impedido quem tenha participado ou venha a participar como perito, testemunha ou representante.","","p08c",{}),
("P08",["18"],"C","conceito_correto",2,"É impedido de atuar em processo administrativo o servidor que tenha interesse direto ou indireto na matéria.","Art. 18, I.","","p08d",{}),
("P08",["19"],"C","consequencia",2,"A autoridade ou servidor que incorrer em impedimento deve comunicar o fato à autoridade competente e abster-se de atuar; a omissão desse dever constitui falta grave, para efeitos disciplinares.","Art. 19, caput e parágrafo único.","","p08e",{}),
("P08",["19"],"E","consequencia",2,"A omissão do dever de comunicar o impedimento constitui mera irregularidade formal, sem consequência disciplinar para o servidor, desde que ele se abstenha de decidir.","Art. 19, parágrafo único: a omissão constitui falta grave, para efeitos disciplinares.","reduz a omissão a irregularidade","p08e",{}),
("P08",["21"],"C","troca_efeito",2,"O indeferimento de alegação de suspeição pode ser objeto de recurso, o qual não tem efeito suspensivo.","Art. 21.","","p08f",{}),
("P08",["21"],"E","troca_efeito",2,"O indeferimento de alegação de suspeição não admite recurso autônomo, devendo a questão ser reapreciada somente no recurso interposto contra a decisão final do processo.","Art. 21: o indeferimento poderá ser objeto de recurso, sem efeito suspensivo.","nega recurso autônomo","p08f",{}),
]
